import React from "react";
import Container from "react-bootstrap/Container";
import { Jumbotron } from "./migration";
import Row from "react-bootstrap/Row";
import PublicationCard from "./PublicationCard";
import graduateHatIcon from "./graduate_hat.ico";
// Generated by `npm run fetch-publications` from publications.json
import publicationList from "../../editable-stuff/publications.generated.json";

const Publication = ({ heading, SID }) => {
  const googleScholarLink = `https://scholar.google.com/citations?user=${SID}&hl=en`;

  return (
    <Jumbotron fluid id="publications" className="bg-light m-0">
      <Container className="">
        <h2 className="display-4 pb-5 text-center">
          {heading}
          <a href={googleScholarLink} target="_blank" rel="noopener noreferrer">
            <img src={graduateHatIcon} alt="Google Scholar" className="icon-google-scholar" />
          </a>
        </h2>
        <Row>
          {publicationList.map((publication) => (
            <PublicationCard key={publication.id} value={publication} />
          ))}
        </Row>
      </Container>
    </Jumbotron>
  );
};

export default Publication;
